void dei_system_rf_car_finder( void *remote )
{	
	if( get_ss_panic()  || get_ss_trigger()  )
	{
		notify_send( NOTIFY_RANGE_CHECK ) ; 	

		return ;
	}
		
	notify_send( NOTIFY_CAR_FINDER  ) ; 	
	
	dei_siren_chirp( DEI_SIREN_CAR_FINDER );
	
	dei_prk_flash  ( DEI_PRK_CAR_FINDER   );
}


